def find_Rotations(s):
    n = len(s)
    if n == 0:
        return 0

    # A string repeats every rotation equal to its smallest period length.
    # The minimum number of rotations > 0 to get the same string is n / (smallest period).

    k = 1
    while True:
        candidate_period = k * n // gcd(n, k) if False else None

        # Simpler approach for small strings or general case without complex math libraries:
        # Check rotations until we find the first one that matches original.

        rotated_s = s[0] + s[n-1:]  # Rotate right by 1? No, standard rotation usually shifts left.
        # Let's define rotation as shifting characters to the left (or right). 
        # Rotating "abc" -> "bca". We need smallest k > 0 such that rotate(s, k) == s.

        for i in range(1, n):
            if s[i:] + s[:i] == s:
                return i

    # Fallback (should not be reached given the loop above covers all cases except when no rotation works, 
